/**
 * @brief Lower a function signature to IR
 *
 * Lowers the fact a function exists, including it's name, parameters, and
 * return type to the IR. Does not lower the function body.
 *
 * @param ctx The context
 * @param function The function node to lower
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Support function signatures with no parameter list.
static void lower_function_signature(Ctx* ctx, AstNode* function) {
  // Add the function to the IR
  IrFunctionId function_id =
      ir_add_function(ctx, ast_get_node_identifier(ctx, function),
                      ast_get_function_return_type(ctx, function));

  // Check if this function was the main function
  if (ast_node_get_flags(function) & AST_FLAG_MAIN)
    // If so, set the entrypoint to this function
    ctx->ir.entrypoint = function_id;

  // A parameterless definition can omit the parameter list
  if (ast_node_get_child_count(function) <= AST_DEF_PARAM_LIST)
    return;

  // Get the function parameters
  AstNode* params;
  ast_node_get_child(ctx, function, AST_DEF_PARAM_LIST, &params);

  // Add the function parameters to the IR
  size_t param_count = ast_node_get_child_count(params);
  for (size_t i = 0; i < param_count; i++) {
    AstNode* param;
    ast_node_get_child(ctx, params, i, &param);

    AstNode* param_type;
    ast_node_get_child(ctx, param, AST_PARAM_TYPE, &param_type);

    ir_add_parameter(
        ctx, function_id, ast_get_node_identifier(ctx, param),
        ast_to_ir_data_type(ctx, ast_node_get_data_type(param_type)));
  }
}

/**
 * @brief Lower a function body to IR
 *
 * Lowers the function body to the IR.
 *
 * @param ctx The context
 * @param function_id The ID assigned by signature lowering
 * @param function The function node to lower
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Create a function entry block and emit an implicit return.
static void lower_function_body(Ctx* ctx,
                                IrFunctionId function_id,
                                AstNode* function) {
  AstNode* body = ast_node_child(ctx, function, AST_DEF_BODY);
  lower_local_slots(ctx, function_id, body);

  IrBlockId block_id = ir_add_block(ctx, function_id);
  ctx->ir.functions.data[function_id].entrypoint = block_id;

  IrOperand value = lower_statement(ctx, function_id, &block_id, body);
  if (block_id != IR_INVALID_ID)
    emit_return(ctx, function_id, block_id, value);
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Pass the signature ID to each function body.
void lower_ast(Ctx* ctx) {
  // Lower each function signature to IR
  size_t function_count = ast_node_get_child_count(ctx->ast);
  for (size_t i = 0; i < function_count; i++) {
    AstNode* child;
    ast_node_get_child(ctx, ctx->ast, i, &child);

    lower_function_signature(ctx, child);
  }

  // Lower each function body to IR
  for (size_t i = 0; i < function_count; i++) {
    AstNode* child;
    ast_node_get_child(ctx, ctx->ast, i, &child);

    lower_function_body(ctx, i, child);
  }
}
